# Fleet extracts name from installer (EXE) and saves it to PACKAGE_ID
# variable
$softwareName = "Mozilla Firefox"

# The ARM64 build registers as "Mozilla Firefox (AArch64 en-US)"; matching on
# the architecture leaves an x64 Firefox, ESR, Developer Edition, or Nightly on
# the same host alone.
$softwareNameLike = "$softwareName (AArch64 *"

# Some uninstallers require a flag to run silently.
# Each uninstaller might use different argument (usually it's "/S" or "/s")
$uninstallArgs = "/S"

$machineKey = `
 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*'
$machineKey32on64 = `
 'HKLM:\SOFTWARE\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'

$exitCode = 0

try {

[array]$uninstallKeys = Get-ChildItem `
    -Path @($machineKey, $machineKey32on64) `
    -ErrorAction SilentlyContinue |
        ForEach-Object { Get-ItemProperty $_.PSPath }

$foundUninstaller = $false
foreach ($key in $uninstallKeys) {
    # If needed, add -notlike to the comparison to exclude certain similar
    # software
    if ($key.DisplayName -like $softwareNameLike -and
        $key.DisplayName -notlike "*ESR*") {
        $foundUninstaller = $true
        # Get the uninstall command. Some uninstallers do not include
        # 'QuietUninstallString' and require a flag to run silently.
        $uninstallCommand = if ($key.QuietUninstallString) {
            $key.QuietUninstallString
        } else {
            $key.UninstallString
        }

        # The uninstall command may contain command and args, like:
        # "C:\Program Files\Software\uninstall.exe" --uninstall --silent
        # Split the command and args
        $splitArgs = $uninstallCommand.Split('"')
        if ($splitArgs.Length -gt 1) {
            if ($splitArgs.Length -eq 3) {
                $uninstallArgs = "$( $splitArgs[2] ) $uninstallArgs".Trim()
            } elseif ($splitArgs.Length -gt 3) {
                Throw `
                    "Uninstall command contains multiple quoted strings. " +
                        "Please update the uninstall script.`n" +
                        "Uninstall command: $uninstallCommand"
            }
            $uninstallCommand = $splitArgs[1]
        }
        Write-Host "Uninstall command: $uninstallCommand"
        Write-Host "Uninstall args: $uninstallArgs"

        $processOptions = @{
            FilePath = $uninstallCommand
            PassThru = $true
        }
        if ($uninstallArgs -ne '') {
            $processOptions.ArgumentList = "$uninstallArgs"
        }

        $process = Start-Process @processOptions
        $null = $process.Handle
        # The uninstaller hands off to a copy of itself, which waits on the Default Browser
        # Agent's cleanup; as SYSTEM that cleanup can hang. Wait for the uninstall entry to go
        # away, ending the agent's cleanup if it's still running after a minute.
        $installDir = Split-Path (Split-Path $uninstallCommand)
        $agentDeadline = (Get-Date).AddSeconds(60)
        $deadline = (Get-Date).AddSeconds(300)
        while ($true) {
            $agent = @(Get-CimInstance Win32_Process | Where-Object {
                $_.ExecutablePath -like "$installDir\*" -and
                ($_.Name -eq 'default-browser-agent.exe' -or $_.CommandLine -like '*--backgroundtask*')
            })
            $registered = (Get-ItemProperty -Path $key.PSPath -ErrorAction SilentlyContinue).DisplayName -like $softwareNameLike
            if (-not $registered -and $agent.Count -eq 0) {
                break
            }
            if ((Get-Date) -gt $deadline) {
                Throw "Firefox is still installed after 300 seconds."
            }
            if ($agent.Count -gt 0 -and (Get-Date) -gt $agentDeadline) {
                $agent | ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }
            }
            Start-Sleep -Seconds 2
        }
        $exitCode = $process.ExitCode

        # Prints the exit code
        Write-Host "Uninstall exit code: $exitCode"
        # Exit the loop once the software is found and uninstalled.
        break
    }
}

if (-not $foundUninstaller) {
    Write-Host "Uninstaller for '$softwareName' not found."
    # Change exit code to 0 if you don't want to fail if uninstaller is not
    # found. This could happen if program was already uninstalled.
    $exitCode = 1
}

} catch {
    Write-Host "Error: $_"
    $exitCode = 1
}

Exit $exitCode
